    public boolean verifyCertificate(String certificate, String knownHash) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] encodedHash = digest.digest(certificate.getBytes(StandardCharsets.UTF_8));

            StringBuilder hexString = new StringBuilder();
            for (byte b : encodedHash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(hex);
            }
            return hexString.toString().equals(knownHash);
        } catch (NoSuchAlgorithmException e) {
            // This should ideally not happen as SHA-256 is a standard algorithm
            System.err.println("SHA-256 algorithm not found: " + e.getMessage());
            return false;
        }
    }

