import javax.crypto.spec.IvParameterSpec;

public class ClassX {
    /**
     * Генерирайте отпечатък за зададения ключ и iv.
     * 
     * :param key: Ключът, използван за криптиране.
     * :param iv: iv, използван за криптиране.
     */
    public String generateFingerprint(byte[] key, byte[] iv) throws Exception {
        SecretKeySpec secretKey = new SecretKeySpec(key, "AES");
        IvParameterSpec ivSpec = new IvParameterSpec(iv);

        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivSpec);

        // For fingerprinting, we can encrypt a fixed, known string.
        // The resulting ciphertext will serve as the "fingerprint"
        // for the given key and IV combination.
        byte[] fixedInput = "This is a fixed string for fingerprinting purposes.".getBytes("UTF-8");
        byte[] encryptedFingerprint = cipher.doFinal(fixedInput);

        // Convert the byte array to a hexadecimal string for easy representation
        StringBuilder hexString = new StringBuilder();
        for (byte b : encryptedFingerprint) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
