    public void encryptAndSendMessage(byte[] secret_key, OutputStream channel, byte[] message) throws Exception {
        // IV (Initialization Vector) - For AES/CBC/PKCS5Padding, a 16-byte IV is typically used.
        // It should be unique for each encryption. For simplicity in this example,
        // we'll use a zeroed IV, but in a real-world scenario, you should generate a random one
