import java.io.IOException;

public class ClassX {

    /**
     * Elimina l'immagine dal percorso fornito nella directory corrente se esiste.
     * 
     * @param path Il percorso dell'immagine da eliminare.
     * @return true se l'immagine è stata eliminata con successo o non esisteva, false altrimenti.
     */
    public boolean deleteImage(String path) {
        if (path == null || path.trim().isEmpty()) {
            // No path provided, nothing to delete. Consider it "successful" in not needing deletion.
            return true;
        }

        File imageFile = new File(path);

        if (imageFile.exists()) {
            try {
                if (imageFile.delete()) {
                    // File was deleted successfully
                    return true;
                } else {
                    // File exists but could not be deleted (e.g., locked by another process)
                    // Log an error if a logger is available
                    System.err.println("Failed to delete image: " + path);
                    return false;
                }
            } catch (SecurityException e) {
                // Permission denied
                System.err.println("Security permission denied to delete image: " + path + " - " + e.getMessage());
                return false;
            }
        } else {
            // File does not exist, so nothing to delete. Consider it successful.
            return true;
        }
    }
}
