import java.util.Optional;

public class ClassX {

    /**
     * Erhalte die Ziel-URL aus der Anfrage mit 'target_url' und überprüfe, ob sie mit '.com/' endet. Wenn ja, gib 'True' zurück, andernfalls gib 'False' zurück.
