    public boolean checkTargetUrlEndsWithCom(String targetUrl) {
        return Optional.ofNullable(targetUrl)
                       .filter(url -> !url.trim().isEmpty())
                       .map(url -> url.endsWith(".com/"))
                       .orElse(false);
    }
}
