     * @param data داده‌هایی که در آنها جستجو انجام می‌شود.
     * @return نتیجه جستجو
     */
    public String searchForPattern(String regexPattern, String data) {
        Pattern pattern = Pattern.compile(regexPattern);
        Matcher matcher = pattern.matcher(data);

        if (matcher.find()) {
            return "مطابقت پیدا شد";
        } else {
            return "هیچ مطابقتی پیدا نشد";
        }
    }
}
