import java.util.logging.Logger;

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Log gegevens van verzoek en retourneer het.
     * @param requestData De gegevens van het verzoek die gelogd moeten worden.
     * @return De oorspronkelijke gegevens van het verzoek.
     */
    public String logAndReturnRequest(String requestData) {
        logger.info("Verzoek ontvangen: " + requestData);
        return requestData;
    }

    /**
     * Een voorbeeldmethode die laat zien hoe een fout gelogd kan worden.
     * @param errorMessage Het foutbericht.
     * @param e De uitzondering die de fout veroorzaakte.
     */
    public void logError(String errorMessage, Exception e) {
        logger.severe(errorMessage + " - Uitzondering: " + e.getMessage());
    }

    /**
     * Een voorbeeldmethode die laat zien hoe een waarschuwing gelogd kan worden.
     * @param warningMessage Het waarschuwingsbericht.
     */
    public void logWarning(String warningMessage) {
        logger.warning(warningMessage);
    }

    /**
     * Een voorbeeld van de main-methode om de logging te testen.
     */
    public static void main(String[] args) {
        ClassX classX = new ClassX();

        // Test de logAndReturnRequest methode
        String data = "Dit zijn testgegevens van het verzoek.";
        String returnedData = classX.logAndReturnRequest(data);
        System.out.println("Teruggegeven gegevens: " + returnedData);

        // Test de logWarning methode
        classX.logWarning("Dit is een waarschuwing dat iets ongebruikelijks is gebeurd.");

        // Test de logError methode
        try {
            int result = 10 / 0; // Dit zal een ArithmeticException veroorzaken
        } catch (ArithmeticException e) {
            classX.logError("Fout bij delen door nul", e);
        }
    }
}
