import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class ClassX {
    /**
     * Statik bir vektör oluşturun, AES ve CBC modunu kullanarak bir şifreleme yapın. Ardından, veriyi blok boyutuna kadar doldurarak şifreleyin ve geri döndürün.
     * @param data: Şifrelenecek veri.
     * @param key: Şifreleme anahtarı.
     * @return: Şifrelenmiş veri.
     */
    public String encrypt(String data, String key) {
        try {
            // Statik IV (Initialization Vector) oluşturma
            // AES'in blok boyutu 128 bit (16 byte) olduğu için IV de 16 byte olmalıdır.
            byte[] iv = new byte[16]; // Tüm byte'lar varsayılan olarak 0 olacak

            IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);
            SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes("UTF-8"), "AES");

            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding"); // PKCS5Padding, veriyi blok boyutuna kadar doldurur
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

            byte[] encryptedData = cipher.doFinal(data.getBytes("UTF-8"));

            return Base64.getEncoder().encodeToString(encryptedData);

        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
