        // 2. Cifra usando AES e modo CBC, preenchendo até o tamanho do bloco (PKCS5Padding é o padrão para AES/CBC)
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);

        // 3. Criptografe os dados
        byte[] encryptedBytes = cipher.doFinal(data.getBytes("UTF-8"));

        // Retorne os dados criptografados em Base64 para facilitar a manipulação como String
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }
