import jakarta.servlet.http.HttpServletRequest;

public class ClassX {
    /**
     * Get the name from the request and send it back to the user in this format: 'Hello <name>!'.
     * @param request The HttpServletRequest containing the name parameter.
     * @return A greeting string in the format 'Hello <name>!' or 'Hello Guest!' if name is not found.
     */
    public String greetUser(HttpServletRequest request) {
        String name = request.getParameter("name");
