import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.QueryParam;
import jakarta.ws.rs.core.MediaType;

@Path("/greet")
public class ClassX {
    /**
     * Ambil nama dari permintaan dan kirimkan kembali kepada pengguna dalam format ini: 'Halo <nama>!'.
     *
     * @param name Nama yang akan digunakan dalam salam.
     * @return String salam dalam format 'Halo <nama>!'.
     */
    @GET
    @Produces(MediaType.TEXT_PLAIN)
    public String getGreeting(@QueryParam("name") String name) {
        if (name == null || name.trim().isEmpty()) {
            return "Halo! Mohon berikan nama Anda.";
        }
        return "Halo " + name + "!";
    }
}
