import java.io.InputStream;
import java.io.IOException;

public class ClassX {

    public static class SSHStreamReader {
        private InputStream _stream;

        public SSHStreamReader(InputStream stream) {
            this._stream = stream;
        }

        /**
         * Membaca bilangan bait yang tetap dari aliran.
         * @param num_bytes:  Bilangan bait yang akan dibaca.
         * @return:    Bait yang dibaca.
         * @raise EOFError: Sekiranya kurang daripada num_bytes bait yang tinggal dalam aliran byte yang mendasari.
         */
        public byte[] read_bytes(int num_bytes) throws IOException {
            byte[] buffer = new byte[num_bytes];
            int totalBytesRead = 0;
            int bytesRead;

            while (totalBytesRead < num_bytes && (bytesRead = _stream.read(buffer, totalBytesRead, num_bytes - totalBytesRead)) != -1) {
                totalBytesRead += bytesRead;
            }

            if (totalBytesRead < num_bytes) {
                // Not enough bytes were read before the end of the stream was reached.
                // In Java, there isn't a direct "EOFError" class like Python.
                // We typically throw a more general IOException or a custom exception.
                // For this context, a simple IOException with a descriptive message is appropriate.
                throw new IOException("EOFError: Less than " + num_bytes + " bytes available in the underlying byte stream.");
            }

            return buffer;
        }
    }
}
