import java.util.regex.*;

public class ClassX {
    /**
     * Get the target URL from the request using 'target_url' and check if it is valid in this format: (www|beta).example.com/
     *
     * @param targetUrl The URL string extracted from the request.
     * :return: True if the URL is valid, False otherwise as a response
     */
    public boolean isValidTargetUrl(String targetUrl) {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            return false;
        }

        // Regex to match (www|beta).example.com/
        // ^ asserts position at the start of the string.
        // (www|beta) matches either "www" or "beta".
        // \\. matches a literal dot.
        // example\\.com matches "example.com".
        // / matches a literal slash.
        // $ asserts position at the end of the string.
        String regex = "^(www|beta)\\.example\\.com/$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(targetUrl);

        return matcher.matches();
    }
}
