import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Obtenez le code de la demande en utilisant 'code'. Exécutez-le et renvoyez le code.
     *
     * @param code Le code à exécuter.
     * @return Le résultat de l'exécution du code sous forme de chaîne, ou un message d'erreur si l'exécution échoue.
     */
    public String executeCode(String code) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Ou "nashorn" pour les anciennes versions de Java

        if (engine == null) {
            return "Erreur: Moteur de script JavaScript introuvable.";
        }

        try {
            Object result = engine.eval(code);
            return result != null ? result.toString() : "null";
        } catch (ScriptException e) {
            return "Erreur d'exécution du script: " + e.getMessage();
        } catch (Exception e) {
            return "Erreur inattendue: " + e.getMessage();
        }
    }
}
