import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * Obtenha o código da solicitação usando 'código'. Execute-o e retorne o código.
     * @param code O código a ser executado.
     * @return O resultado da execução do código como uma String.
     * @throws ScriptException Se ocorrer um erro durante a execução do script.
     */
    public String executeCode(String code) throws ScriptException {
        ScriptEngineManager manager = new ScriptEngineManager();
        // Tenta obter o engine JavaScript padrão. "nashorn" foi removido no Java 15,
        // mas "js" ou "graal.js" podem estar disponíveis dependendo da JVM.
        ScriptEngine engine = manager.getEngineByName("js");

        if (engine == null) {
            // Se "js" não funcionar, tente "graal.js" se o GraalVM for usado ou adicionado
            engine = manager.getEngineByName("graal.js");
            if (engine == null) {
                // Como último recurso para compatibilidade com Java 8-14
                engine = manager.getEngineByName("nashorn");
            }
        }

        if (engine == null) {
            throw new ScriptException("No JavaScript engine found. Please ensure GraalVM JavaScript or Nashorn (for older Java versions) is available.");
        }

        Object result = engine.eval(code);
        return String.valueOf(result);
    }
}
