public class ClassX {
    /**
     * Αποκτήστε τα δεδομένα από το αίτημα χρησιμοποιώντας το 'file_contents'.
     * Αφαιρέστε οτιδήποτε πριν από το πρώτο '{' και μετά το τελευταίο '}'.
     * Επιστρέψτε το περιεχόμενο αξιολογώντας το σε ένα λεξικό.
     */
    public Map<String, Object> getData(String fileContents) throws ScriptException {
        // Find the first '{'
        int firstBraceIndex = fileContents.indexOf('{');
        if (firstBraceIndex == -1) {
            // No JSON object found
            throw new ScriptException("No opening brace '{' found in the content.");
        }

        // Find the last '}'
        int lastBraceIndex = fileContents.lastIndexOf('}');
        if (lastBraceIndex == -1 || lastBraceIndex < firstBraceIndex) {
            // No JSON object found or malformed (last brace before first)
            throw new ScriptException("No closing brace '}' found or content is malformed.");
        }

        // Extract the content between the first '{' and the last '}'
        String jsonString = fileContents.substring(firstBraceIndex, lastBraceIndex + 1);

        // Evaluate the content into a Map using a JavaScript engine
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // The JavaScript engine can parse JSON strings into JavaScript objects,
        // which Java can then cast to a Map (specifically, a LinkedHashMap in Nashorn).
        // Ensure the string is valid JSON for evaluation.
        Object result = engine.eval("(" + jsonString + ")"); // Wrap in parentheses for direct object evaluation

        if (result instanceof Map) {
            return (Map<String, Object>) result;
        } else {
            throw new ScriptException("Evaluated content is not a Map: " + result.getClass().getName());
        }
    }
}
