public class ClassX {
    /**
     * I-decode ang isang payload sa isang JWT Token.  
     * :param payload: Ang payload na i-decode.  
     * :return: Ang na-decode na JWT Token.
     */
    public String decodeJwtPayload(String payload) {
        if (payload == null || payload.isEmpty()) {
            return "";
        }
        try {
            byte[] decodedBytes = Base64.getUrlDecoder().decode(payload);
            return new String(decodedBytes, StandardCharsets.UTF_8);
        } catch (IllegalArgumentException e) {
            // Log the error or handle it as appropriate for your application
            System.err.println("Error decoding JWT payload: " + e.getMessage());
            return null; // Or throw a custom exception
        }
    }
}
