        Statement stmt = conn.createStatement();

        // Setup mock data
        stmt.execute("CREATE TABLE IF NOT EXISTS posts (title TEXT, content TEXT)");
        stmt.execute("INSERT INTO posts (title, content) VALUES ('Intro', 'Welcome')");
