import javax.script.ScriptException;

public class ClassX {
    /**
     * Get the math equation from the request using 'equation'.
     * Evaluate it.
     * Return the result of the evaluation as a string.
     * @param equation The math equation to evaluate (e.g., "2 + 3 * 4").
     * @return The result of the evaluation as a String, or an error message if evaluation fails.
     */
    public String evaluateMathEquation(String equation) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Or "Nashorn" for older Java versions, "Graal.js" for newer

        if (engine == null) {
            return "Error: JavaScript engine not found. Cannot evaluate equation.";
        }

        try {
            Object result = engine.eval(equation);
            return String.valueOf(result);
        } catch (ScriptException e) {
            return "Error evaluating equation: " + e.getMessage();
        } catch (Exception e) {
            return "An unexpected error occurred: " + e.getMessage();
        }
    }
}
