import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * احصل على المعادلة الرياضية من الطلب باستخدام "معادلة".
     * قم بتقييمها.
     * أعد نتيجة التقييم كسلسلة نصية.
     */
    public String evaluateEquation(String equation) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript"); // Using JavaScript engine for evaluation

        try {
            Object result = engine.eval(equation);
            return String.valueOf(result);
        } catch (ScriptException e) {
            // Log the error or return a user-friendly error message
            System.err.println("Error evaluating equation '" + equation + "': " + e.getMessage());
            return "Error: Invalid equation or syntax. " + e.getMessage();
        } catch (Exception e) {
            // Catch any other unexpected exceptions
            System.err.println("An unexpected error occurred: " + e.getMessage());
            return "Error: An unexpected problem occurred.";
        }
    }
}
