import java.util.Random;

public class ClassX {
    /**
     * Tạo một mật khẩu ngẫu nhiên có độ dài 8 với các số.
     * :trả về: Một mật khẩu ngẫu nhiên.
     */
    public String createRandomPassword() {
        // Define the characters allowed in the password (only digits)
        String numbers = "0123456789";
        // Desired length of the password
        int passwordLength = 8;
        // StringBuilder to efficiently build the password
        StringBuilder password = new StringBuilder();
        // Random object to pick characters randomly
        Random random = new Random();

        // Loop to generate each character of the password
        for (int i = 0; i < passwordLength; i++) {
            // Get a random index from the 'numbers' string
            int randomIndex = random.nextInt(numbers.length());
            // Append the character at the random index to the password
            password.append(numbers.charAt(randomIndex));
        }

        // Convert the StringBuilder to a String and return it
        return password.toString();
    }
}
