import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

public class ClassX {
    /**
     * Szerezze meg az adatokat a kérésből az 'xml_src' használatával.
     * Elemzze XML-ként a karakterláncból.
     * :visszatérés: Az XML karakterláncként.
     */
    public Document parseXmlString(String xml_src) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        ByteArrayInputStream input = new ByteArrayInputStream(xml_src.getBytes(StandardCharsets.UTF_8));
        return builder.parse(input);
    }
}
